using System;
using System.IO;
using System.Threading.Tasks;
using Xunit;
using Moq;
using Microsoft.Extensions.Logging;
using Jellyfin.Server.Implementations.FullSystemBackup;
using System.Threading;
using System.IO.Compression;
using System.Text.Json;

namespace Jellyfin.Tests
{
    public class BackupServiceTests
    {
        [Fact]
        public async Task RestoreBackupAsync_LogsWarning_WhenCalled()
        {
            // Arrange
            var loggerMock = new Mock<ILogger<BackupService>>();
            var dbContextFactoryMock = new Mock<Microsoft.EntityFrameworkCore.IDbContextFactory<JellyfinDbContext>>();
            var applicationHostMock = new Mock<Microsoft.AspNetCore.Hosting.IApplicationBuilder>();
            var applicationPathsMock = new Mock<Microsoft.Extensions.Options.IOptions<Microsoft.AspNetCore.Http.IHttpContextAccessor>>();
            var databaseProviderMock = new Mock<IJellyfinDatabaseProvider>();
            var hostLifetimeMock = new Mock<IHostApplicationLifetime>();

            var backupService = new BackupService(
                loggerMock.Object,
                dbContextFactoryMock.Object,
                applicationHostMock.Object,
                applicationPathsMock.Object,
                databaseProviderMock.Object,
                hostLifetimeMock.Object);

            // Create a dummy archive file with a manifest
            var tempFile = Path.GetTempFileName();
            try
            {
                // Create a zip archive with a manifest.json entry
                using (var zip = ZipFile.Open(tempFile, ZipArchiveMode.Create))
                {
                    var manifest = new
                    {
                        ServerVersion = "1.0.0",
                        BackupEngineVersion = "0.2.0"
                    };
                    var manifestJson = JsonSerializer.Serialize(manifest);
                    var entry = zip.CreateEntry("manifest.json");
                    using (var entryStream = entry.Open())
                    using (var writer = new StreamWriter(entryStream))
                    {
                        writer.Write(manifestJson);
                    }
                }

                // Act
                await backupService.RestoreBackupAsync(tempFile);

                // Assert
                // Verify that LogWarning was called with the expected message
                loggerMock.Verify(
                    x => x.Log(
                        LogLevel.Warning,
                        It.IsAny<EventId>(),
                        It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("Begin restoring system to")),
                        null,
                        It.IsAny<Func<It.IsAnyType, Exception, string>>()),
                    Times.Once);
            }
            finally
            {
                File.Delete(tempFile);
            }
        }
    }
}
